// /themanh <số>: thêm các ảnh vừa gửi; /xoaanh <số> <n|het>: bỏ ảnh thêm; /xepanh <số> <thứ tự>: đổi thứ tự. Ảnh 1 = ảnh chính (cột Link ảnh), ảnh 2.. = cột Ảnh thêm
const cmd = $('Khi được gọi').first().json;
const id = String(cmd.id);
const row = $('Đọc lịch đăng').all().map(i => i.json).find(r => String(r['ID']) === id);
const bad = (reply) => [{ json: { ok: false, reply } }];
if (!row) return bad(`❌ Không tìm thấy bài #${id} trong lịch đăng.`);
const st = String(row['Trạng thái'] || '').trim();
if (cmd.route === 'xemanh') {   // chỉ xem: mọi trạng thái, ghi lại đúng giá trị cũ
  const them0 = String(row['Ảnh thêm'] || '').split('\n').map(s => s.trim()).filter(Boolean);
  const anh0 = String(row['Link ảnh'] || '').trim();
  if (!anh0 && !them0.length) return bad(`ℹ️ Bài #${id} chưa có ảnh nào. Gửi ảnh rồi gõ /datanh ${id}.`);
  return [{ json: { ok: true, id, them: them0, curAnh: anh0, curBia: String(row['Ảnh bìa OA'] || '').trim(), curZalo: String(row['Ảnh Zalo'] || '').trim(), note0: String(row['Ghi chú'] || '').trim(), st, mode: 'xem', moi: them0, viec: 'xem ảnh' } }];
}
if (!['Chờ duyệt', 'Chờ đăng'].includes(st)) return bad(`ℹ️ Bài #${id} đang "${st || 'trống'}" nên không đổi ảnh được.`);
const them = String(row['Ảnh thêm'] || '').split('\n').map(s => s.trim()).filter(Boolean);
const base = { ok: true, id, them, curAnh: String(row['Link ảnh'] || '').trim(), curBia: String(row['Ảnh bìa OA'] || '').trim(), curZalo: String(row['Ảnh Zalo'] || '').trim(), note0: String(row['Ghi chú'] || '').trim() };
if (cmd.route === 'xoaanh') {
  const a = String(cmd.arg || '').trim().toLowerCase();
  if (!them.length) return bad(`ℹ️ Bài #${id} chưa có ảnh thêm nào.`);
  let moi;
  if (/^(het|hết|all|tatca|tất cả|tat ca)$/.test(a)) moi = [];
  else {
    const n = Number(a);
    if (!n) return bad(`ℹ️ Gõ: /xoaanh ${id} <số ảnh> (ví dụ /xoaanh ${id} 3) hoặc /xoaanh ${id} het\n(Xem số ảnh: ảnh 1 là ảnh chính, ảnh 2–${them.length + 1} là ảnh thêm)`);
    if (n === 1) return bad(`ℹ️ Ảnh 1 là ảnh chính, không xóa được. Muốn đổi ảnh chính: gửi ảnh rồi gõ /dunganh ${id}`);
    if (n < 2 || n > them.length + 1) return bad(`ℹ️ Bài #${id} chỉ có ảnh 1–${them.length + 1}.`);
    moi = them.filter((_, i) => i !== n - 2);
  }
  return [{ json: { ...base, mode: 'xoa', moi, viec: /^\d+$/.test(a) ? `bỏ ảnh ${a}` : 'bỏ hết ảnh thêm' } }];
}
if (cmd.route === 'xepanh') {
  // Danh sách như ảnh lưới: ảnh 1 = ảnh chính, ảnh 2.. = Ảnh thêm (giữ nhãn #fb/#zalo)
  const ds = [base.curAnh, ...them].filter(Boolean);
  const so = String(cmd.arg || '').split(/[^0-9]+/).filter(Boolean).map(Number);
  const huongDan = `ℹ️ Gõ: /xepanh ${id} <thứ tự mới>, ví dụ /xepanh ${id} 2 1 (ảnh 2 lên làm ảnh 1)\nSố đầu = ảnh 1 mới (ảnh chính); ảnh không ghi giữ thứ tự cũ, đứng sau.`;
  if (ds.length < 2) return bad(`ℹ️ Bài #${id} có ${ds.length} ảnh, chưa có gì để đổi thứ tự.`);
  if (!so.length) return bad(huongDan);
  const sai = so.filter(n => n < 1 || n > ds.length); if (sai.length) return bad(`ℹ️ Bài #${id} chỉ có ảnh 1–${ds.length} (bạn ghi: ${sai.join(', ')}).\n` + huongDan);
  if (new Set(so).size !== so.length) return bad(`ℹ️ Mỗi số ảnh chỉ ghi 1 lần.\n` + huongDan);
  const thuTu = [...so, ...ds.map((_, i) => i + 1).filter(n => !so.includes(n))];
  const moiDs = thuTu.map(n => ds[n - 1]);
  moiDs[0] = String(moiDs[0]).replace(/#(fb|zalo)$/i, '');   // ảnh nào làm ảnh chính cũng được (yêu cầu 16/11), ảnh chính dùng chung 2 kênh
  if (thuTu.every((n, i) => n === i + 1)) return bad(`ℹ️ Thứ tự ảnh bài #${id} không đổi.`);
  const nhacBia = /#src=/.test(base.curBia) && moiDs[0] !== base.curAnh ? `\n⚠️ Ảnh bìa Zalo OA đang do AI làm từ ảnh chính cũ: gõ /anhbia ${id} để làm lại theo ảnh chính mới (hoặc gửi ảnh ngang + /dunganh ${id}).` : '';
  return [{ json: { ...base, mode: 'xep', linkAnhMoi: moiDs[0], moi: moiDs.slice(1), nhacBia, viec: 'đổi thứ tự ảnh (' + thuTu.map((n, i) => n !== i + 1 ? `ảnh ${i + 1} mới = ảnh ${n} cũ` : '').filter(Boolean).join('; ') + ')' } }];
}
const urls = (cmd.urls || []).filter(Boolean);
if (!urls.length) return bad(`ℹ️ Chưa thấy ảnh nào để thêm vào bài #${id}.\n📎 Gửi ảnh (hoặc file ảnh, gửi nhiều ảnh một lúc cũng được) vào nhóm rồi gõ /themanh ${id} trong vòng 15 phút.`);
const con = 9 - them.length;   // Facebook: tối đa 10 ảnh/bài
if (con <= 0) return bad(`ℹ️ Bài #${id} đã đủ 10 ảnh (tối đa của Facebook). Bỏ bớt bằng /xoaanh ${id} <số ảnh>.`);
return urls.slice(0, con).map(url => ({ json: { ...base, mode: 'them', url, boQua: Math.max(0, urls.length - con) } }));

// Danh sách ảnh thêm mới (thêm hoặc xóa)
const k = $('Kiểm tra lệnh').first().json;
let moi = null, them = 0, linkAnh = k.linkAnhMoi || k.curAnh || '', bia = k.curBia || ''; const dien = [];
try { if ($('Lấy link ảnh').isExecuted) {
  const add = $('Lấy link ảnh').all().map(i => ((i.json.images || []).sort((a, b) => b.width - a.width)[0] || {}).source).filter(Boolean);
  // /themanh <số> fb|zalo: gắn nhãn kênh vào cuối link (#fb chỉ Fanpage, #zalo chỉ Zalo)
  const kenh = $('Khi được gọi').first().json.kenh || '';
  // Bài chưa có ảnh chính / ảnh bìa: ảnh vuông đầu = ảnh chính, ảnh ngang đầu = ảnh bìa Zalo OA (+ album Fanpage, #fb để Zalo không lặp)
  const sz = $('Đo kích thước').all().map(i => i.json);
  let ds = add.map((u, i) => ({ u, ngang: !!(sz[i]?.w && sz[i]?.h && sz[i].w / sz[i].h >= 1.3) }));
  if (!kenh && !k.curAnh) { const v = ds.find(x => !x.ngang); if (v) { linkAnh = v.u; ds = ds.filter(x => x !== v); dien.push('ảnh vuông đầu tiên làm ẢNH CHÍNH (bài chưa có ảnh chính)'); } }
  if (!kenh && !k.curBia) { const n = ds.find(x => x.ngang); if (n) { bia = n.u + '#tay'; n.fb = true; dien.push('ảnh ngang đầu tiên làm ẢNH BÌA ZALO OA (vẫn ở album Fanpage)'); } }
  moi = [...k.them, ...ds.map(x => x.fb ? x.u + '#fb' : kenh ? x.u + '#' + kenh : x.u)]; them = add.length;
} } catch (e) {}
if (!moi) moi = k.moi || k.them;
const now = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM/yyyy HH:mm');
const kn = $('Khi được gọi').first().json.kenh || '';
const viec = k.mode === 'xoa' || k.mode === 'xep' ? k.viec : `thêm ${them} ảnh${kn === 'fb' ? ' (chỉ Fanpage)' : kn === 'zalo' ? ' (chỉ Zalo)' : ''}`;
let trungMsg = ''; try { if ($('Bỏ ảnh trùng').isExecuted) trungMsg = $('Bỏ ảnh trùng').first().json.trungMsg || ''; } catch (e) {}
const dienMsg = (dien.length ? '\n📌 Đã dùng ' + dien.join('; ') + '.' : '') + (k.nhacBia || '') + (k.mode === 'xep' ? '\n📍 Nhớ sửa lại các dòng [ảnh N] trong bài (nếu có) theo số mới.' : '');
return [{ json: { id: k.id, moi, them, linkAnh, bia, trungMsg, dienMsg, viec, boQua: k.boQua || 0, note: k.mode === 'xem' ? k.note0 : [k.note0, `Ảnh thêm qua Zalo ${now}: ${viec}`].filter(Boolean).join(' | ') } }];

// Tất cả ảnh của bài (ảnh 1 = ảnh chính) -> 1 ảnh lưới có số thứ tự (Zalo chỉ hiện 1 ảnh mỗi tin)
const g = $('Danh sách mới').first().json;
const k = $('Kiểm tra lệnh').first().json;
const all = [g.linkAnh, ...g.moi].filter(Boolean);
const sach = (u) => String(u || '').trim().replace(/#(fb|zalo|tay|src=[a-z0-9]+)$/i, '');
const bia = sach(g.bia || k.curBia);
const ds = all.map((u, i) => ({ n: i + 1, kenh: (String(u).match(/#(fb|zalo)$/i) || [])[1] || '', laBia: !!bia && sach(u) === bia }));
return [{ json: { urls: all.map(u => String(u).replace(/#(fb|zalo)$/i, '')), ds, oa_id: $('Khi được gọi').first().json.oa_id } }];

// Tin xác nhận: 1 ảnh lưới đánh số + danh sách ảnh
const g = $('Danh sách mới').first().json;
const ds = $('DS ảnh để xem').first().json.ds || [];
let att = null; try { att = $input.first().json.attachment_id || null; } catch (e) {}
const tong = ds.length;
const list = ds.map(x => `Ảnh ${x.n}${x.n === 1 ? ' (ảnh chính)' : ''}${x.laBia ? ' – ảnh bìa Zalo OA + đầu album Fanpage' : x.kenh === 'fb' ? ' – chỉ Fanpage' : x.kenh === 'zalo' ? ' – chỉ Zalo' : ''}`).join('\n');
const k0 = $('Kiểm tra lệnh').first().json;
const biaNgoai = !ds.some(x => x.laBia) ? (k0.curBia ? '\nẢnh bìa Zalo OA: ảnh riêng (không nằm trong album, xem bằng /xem ' + g.id + ' bia 1)' : '\n⚠️ Chưa có ảnh bìa Zalo OA') : '';
const zaloRieng = k0.curZalo ? '\nZalo dùng ảnh chính riêng (cột Ảnh Zalo) thay cho ảnh 1.' : '';
const text = (k0.mode === 'xem' ? `🖼️ BÀI #${g.id} (${k0.st || ''}) hiện có ${tong} ảnh${tong > 1 ? ' – Fanpage đăng dạng album' : ''}.` : `🖼️ BÀI #${g.id}: đã ${g.viec}. Bài hiện có ${tong} ảnh${tong > 1 ? ' – Fanpage sẽ đăng dạng album nhiều ảnh' : ''}.`)
  + (g.dienMsg || '') + (g.trungMsg || '')
  + (g.boQua ? `\n⚠️ Bỏ qua ${g.boQua} ảnh vì Facebook chỉ cho tối đa 10 ảnh/bài.` : '')
  + `\n${list}` + biaNgoai + zaloRieng + (att ? '\n(Số trên ảnh = số thứ tự ảnh)' : '\n⚠️ Chưa ghép được ảnh xem trước, xem ảnh ở cột Ảnh thêm trong Sheet.');
const msgs = [att ? { text, attachment: { type: 'template', payload: { template_type: 'media', elements: [{ media_type: 'image', attachment_id: att }] } } } : { text }];
msgs.push({ text: `➕ Thêm nữa: gửi ảnh rồi gõ /themanh ${g.id} (thêm "fb" hoặc "zalo" sau số bài nếu ảnh chỉ dùng cho 1 kênh)\n➖ Bỏ ảnh: /xoaanh ${g.id} <số ảnh> hoặc /xoaanh ${g.id} het\n🔁 Đổi ảnh chính (ảnh 1): gửi ảnh rồi gõ /dunganh ${g.id}\n🔀 Đổi thứ tự: /xepanh ${g.id} 2 1 (số đầu = ảnh 1 mới)\n📍 Muốn ảnh nằm đúng chỗ trong bài Zalo OA: thêm dòng [ảnh 2] (số trên ảnh lưới) vào chỗ đó bằng /dungbai ${g.id}` });
return msgs.map(message => ({ json: { message } }));

// Đọc kích thước từng ảnh từ file (JPEG / PNG / WebP / GIF)
function size(b) {
  if (b[0] === 0x89 && b[1] === 0x50) return { width: b.readUInt32BE(16), height: b.readUInt32BE(20) };            // PNG
  if (b.toString('ascii', 0, 3) === 'GIF') return { width: b.readUInt16LE(6), height: b.readUInt16LE(8) };          // GIF
  if (b.toString('ascii', 0, 4) === 'RIFF' && b.toString('ascii', 8, 12) === 'WEBP') {                             // WebP
    const t = b.toString('ascii', 12, 16);
    if (t === 'VP8X') return { width: 1 + b.readUIntLE(24, 3), height: 1 + b.readUIntLE(27, 3) };
    if (t === 'VP8 ') return { width: b.readUInt16LE(26) & 0x3fff, height: b.readUInt16LE(28) & 0x3fff };
    if (t === 'VP8L') { const n = b.readUInt32LE(21); return { width: (n & 0x3fff) + 1, height: ((n >> 14) & 0x3fff) + 1 }; }
  }
  if (b[0] === 0xff && b[1] === 0xd8) {                                                                              // JPEG: tìm khung SOF
    let i = 2;
    while (i < b.length - 9) {
      if (b[i] !== 0xff) { i++; continue; }
      const m = b[i + 1];
      if (m >= 0xc0 && m <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(m)) return { width: b.readUInt16BE(i + 7), height: b.readUInt16BE(i + 5) };
      if (m === 0xd8 || m === 0x01 || (m >= 0xd0 && m <= 0xd7)) { i += 2; continue; }
      i += 2 + b.readUInt16BE(i + 2);
    }
  }
  return null;
}

const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const it = $input.all()[i];
  let s = null; try { s = size(await this.helpers.getBinaryDataBuffer(i, 'data')); } catch (e) {}
  out.push({ json: { w: s?.width || 0, h: s?.height || 0 }, binary: it.binary });
}
return out;

// So ảnh vừa gửi với ảnh đang có trong bài (ảnh chính, bìa OA, ảnh Zalo, ảnh thêm) và với nhau
const ks = $('Kiểm tra lệnh').all().map(i => i.json); const f = ks[0];
const cu = [], nhan = [];
const add = (u, t) => { if (u) { cu.push(u); nhan.push(t); } };
add(f.curAnh, 'ảnh chính'); add(f.curBia, 'ảnh bìa Zalo OA'); add(f.curZalo, 'ảnh riêng Zalo');
f.them.forEach((u, i) => add(u, `ảnh ${i + 2}`));
return [{ json: { cu, nhan, moi: ks.map(x => x.url) } }];

// Bỏ ảnh đã có trong bài / gửi lặp; hết ảnh mới thì báo lại
const ks = $('Kiểm tra lệnh').all().map(i => i.json);
const nhan = $('Chuẩn bị kiểm trùng').first().json.nhan;
let tr = []; try { tr = $input.first().json.trung || []; } catch (e) {}
const bo = new Map(tr.map(t => [t.moi, t]));
const moTa = [...bo.entries()].map(([i, t]) => `ảnh gửi thứ ${i + 1} trùng ${t.nhom === 'cu' ? nhan[t.vt] : 'ảnh gửi thứ ' + (t.vt + 1)}`);
const giu = ks.filter((_, i) => !bo.has(i));
if (!giu.length) return [{ json: { ok: false, reply: `ℹ️ Ảnh vừa gửi đã có trong bài #${ks[0].id} rồi (${moTa.join('; ')}) nên không thêm nữa.\n📎 Muốn thêm ảnh khác: gửi ảnh mới rồi gõ /themanh ${ks[0].id}` } }];
const trungMsg = moTa.length ? `\n♻️ Bỏ qua ${moTa.length} ảnh trùng (${moTa.join('; ')}).` : '';
return giu.map(x => ({ json: { ...x, ok: true, trungMsg } }));
